// SPDX-License-Identifier: MIT
// Shardscale (Prismheart campaign), plain C++17 for the Unreal binding. A port of tools/minigames/shardscale.py
// (unreal-team), which stays the rules authority. Seeding is CPython-compatible (DaedalusPyRandomCore.h,
// "shardscale:<seed>:<difficulty>") and the only draws are randrange at setup (repeated until the line is solvable);
// nothing is random after. Byte parity goes through engines/unreal/core-test/shardscale_parity.txt
// (shardscale_core_test.cpp), generated by tools/minigames/shardscale_parity.py.
//
// Rules: a line of shards (weights 1..9) comes off the cart in order. Each turn the next shard goes on the left or
// right pan or onto the bench (Bench slots); a benched shard goes on either pan later. If the pans ever differ by more
// than Cap the beam tips (loss). With every shard placed the beam must be level within Tolerance to win: WinScore +
// SlackScore per point of slack + BenchScore per slot never used. The weigher (demo) is an exact search over
// (index, diff, bench) with actions in the rules' order; the setup redraws until that search finds a level weighing.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <array>
#include <cstdint>
#include <cstdlib>
#include <string>
#include <unordered_map>
#include <vector>

namespace daedalus { namespace shardscale {

inline const char* GameId() { return "shardscale"; }
inline const char* Title() { return "Shardscale"; }

constexpr int MinWeight = 1, MaxWeight = 9;
constexpr int WinScore = 10, SlackScore = 5, BenchScore = 2;
constexpr int MaxRedraws = 50;
constexpr int MaxShards = 16, MaxBench = 3;   // the memo key packs the bench into 16 bits: 3 weights of 4 bits plus the count

struct Difficulty { const char* Name; int Shards; int Cap; int Tolerance; int Bench; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 8, 6, 1, 2 }, { "normal", 10, 5, 1, 2 }, { "hard", 12, 5, 0, 3 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

enum class Kind : int { Left = 0, Right, Hold };
/** An action: a pan (or the bench) and where the shard comes from — Next = the line, else a bench index. */
struct Action
{
	Kind K = Kind::Left; int Source = Next;
	static constexpr int Next = -1;
	bool operator==(const Action& O) const noexcept { return K == O.K && Source == O.Source; }
};
constexpr Action NoAction{ Kind::Hold, -2 };

/** The bench: up to MaxBench weights kept sorted, as Python keeps its list. */
struct Bench
{
	std::array<int, MaxBench> W{}; int N = 0;
	void Add(int Weight) noexcept { W[static_cast<size_t>(N++)] = Weight; std::sort(W.begin(), W.begin() + N); }
	int Take(int I) noexcept { const int Weight = W[static_cast<size_t>(I)]; for (int K = I; K + 1 < N; ++K) W[static_cast<size_t>(K)] = W[static_cast<size_t>(K + 1)]; --N; return Weight; }
	std::uint32_t Key() const noexcept { std::uint32_t K = 0; for (int I = 0; I < N; ++I) K = K * 16u + static_cast<std::uint32_t>(W[static_cast<size_t>(I)]); return K * 4u + static_cast<std::uint32_t>(N); }
};

/** Game.candidate_actions: left/right the next shard, hold it, then left/right each benched shard. */
inline int CandidateActions(int Index, int Shards, const Bench& B, int BenchSize, std::array<Action, 3 + 2 * MaxBench>& Out) noexcept
{
	int N = 0;
	if (Index < Shards)
	{
		Out[static_cast<size_t>(N++)] = { Kind::Left, Action::Next };
		Out[static_cast<size_t>(N++)] = { Kind::Right, Action::Next };
		if (B.N < BenchSize) Out[static_cast<size_t>(N++)] = { Kind::Hold, Action::Next };
	}
	for (int H = 0; H < B.N; ++H)
	{
		Out[static_cast<size_t>(N++)] = { Kind::Left, H };
		Out[static_cast<size_t>(N++)] = { Kind::Right, H };
	}
	return N;
}

/** Game.solve: the first winning action from (Index, Diff, Bench) in the rules' order, or NoAction. Memoised. */
struct Solver
{
	const std::vector<int>& Line; int Cap, Tolerance, BenchSize;
	std::unordered_map<std::uint32_t, Action> Memo;

	Solver(const std::vector<int>& InLine, int InCap, int InTolerance, int InBench) : Line(InLine), Cap(InCap), Tolerance(InTolerance), BenchSize(InBench) {}

	static std::uint32_t Key(int Index, int Diff, const Bench& B) noexcept
	{
		return (static_cast<std::uint32_t>(Index) << 24) | (static_cast<std::uint32_t>(Diff + 64) << 16) | (B.Key() & 0xFFFFu);
	}

	Action Solve(int Index, int Diff, const Bench& B)
	{
		const std::uint32_t K = Key(Index, Diff, B);
		const auto Found = Memo.find(K);
		if (Found != Memo.end()) return Found->second;
		Action Result = NoAction;
		const int Shards = static_cast<int>(Line.size());
		if (Index == Shards && B.N == 0)
		{
			if (std::abs(Diff) <= Tolerance) Result = { Kind::Left, Action::Next };   // any marker: "done, level"
		}
		else
		{
			std::array<Action, 3 + 2 * MaxBench> Acts{};
			const int Count = CandidateActions(Index, Shards, B, BenchSize, Acts);
			for (int I = 0; I < Count; ++I)
			{
				const Action A = Acts[static_cast<size_t>(I)];
				Bench NextBench = B;
				int NextIndex = Index, NextDiff = Diff;
				const int Weight = A.Source == Action::Next ? Line[static_cast<size_t>(Index)] : NextBench.Take(A.Source);
				if (A.Source == Action::Next) ++NextIndex;
				if (A.K == Kind::Hold) NextBench.Add(Weight);
				else
				{
					NextDiff += A.K == Kind::Left ? Weight : -Weight;
					if (std::abs(NextDiff) > Cap) continue;
				}
				if (!(Solve(NextIndex, NextDiff, NextBench) == NoAction)) { Result = A; break; }
			}
		}
		Memo[K] = Result;
		return Result;
	}
};

struct Game
{
	const Difficulty* Diff = nullptr;
	std::vector<int> Line;
	int Index = 0, Left = 0, Right = 0, BenchUsed = 0;
	Bench Held;
	bool Tipped = false;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, Illegal, GameOver };

	int Difference() const noexcept { return Left - Right; }
	int Remaining() const noexcept { return Diff ? Diff->Shards - Index + Held.N : 0; }
	/** Game.fresh: nothing placed yet, so the screen shows its tutorial rows. */
	bool FreshLine() const noexcept { return Index == 0 && !Over; }

	int Actions(std::array<Action, 3 + 2 * MaxBench>& Out) const noexcept
	{
		return Diff ? CandidateActions(Index, Diff->Shards, Held, Diff->Bench, Out) : 0;
	}
	bool IsLegal(const Action& A) const noexcept
	{
		std::array<Action, 3 + 2 * MaxBench> Acts{};
		const int Count = Actions(Acts);
		for (int I = 0; I < Count; ++I) if (Acts[static_cast<size_t>(I)] == A) return true;
		return false;
	}

	/** PrismGame.start + Game.setup: draw lines until the exact search levels one. False on an unknown difficulty. */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff || Diff->Shards > MaxShards || Diff->Bench > MaxBench) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		for (int Attempt = 0; Attempt < MaxRedraws; ++Attempt)
		{
			Line.assign(static_cast<size_t>(Diff->Shards), 0);
			for (int& W : Line) W = MinWeight + static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(MaxWeight - MinWeight + 1)));
			Solver S(Line, Diff->Cap, Diff->Tolerance, Diff->Bench);
			if (!(S.Solve(0, 0, Bench{}) == NoAction)) break;
		}
		Index = Left = Right = BenchUsed = 0; Held = Bench{}; Tipped = false;
		return true;
	}

	/** Game.act. `Result` mirrors the Python result text. */
	Act Step(const Action& A, std::string& Result)
	{
		if (Over) return Act::GameOver;
		if (!IsLegal(A)) return Act::Illegal;
		int Weight = 0;
		if (A.Source == Action::Next) { Weight = Line[static_cast<size_t>(Index)]; ++Index; }
		else Weight = Held.Take(A.Source);
		if (A.K == Kind::Hold)
		{
			Held.Add(Weight); ++BenchUsed;
			Result = "hold " + std::to_string(Weight) + ": bench " + BenchString();
			return Act::Ok;
		}
		if (A.K == Kind::Left) Left += Weight; else Right += Weight;
		const std::string Side = std::string(A.K == Kind::Left ? "left " : "right ") + std::to_string(Weight) + ": pans " + std::to_string(Left) + "/" + std::to_string(Right);
		if (std::abs(Difference()) > Diff->Cap)
		{
			Tipped = true; Over = true; Won = false;
			Result = Side + "; the beam tips and the shards slide off";
			return Act::Ok;
		}
		if (Remaining() == 0)
		{
			const bool Level = std::abs(Difference()) <= Diff->Tolerance;
			if (Level) Score = WinScore + SlackScore * (Diff->Tolerance - std::abs(Difference())) + BenchScore * (Diff->Bench - BenchUsed);
			Over = true; Won = Level;
			Result = Side + (Level ? "; the beam rests level" : "; the beam settles askew");
			return Act::Ok;
		}
		Result = Side;
		return Act::Ok;
	}

	/** Game.preview: (legal, diff after, tips, ends) for an action without taking it. */
	bool Preview(const Action& A, int& After, bool& Tips, bool& Ends) const noexcept
	{
		After = Difference(); Tips = Ends = false;
		if (Over || !IsLegal(A)) return false;
		if (A.K == Kind::Hold) return true;
		const int Weight = A.Source == Action::Next ? Line[static_cast<size_t>(Index)] : Held.W[static_cast<size_t>(A.Source)];
		After += A.K == Kind::Left ? Weight : -Weight;
		Tips = std::abs(After) > Diff->Cap;
		Ends = Remaining() == 1;
		return true;
	}

	/** Game.demo_action, the weigher: the first action of an exact winning line; the lighter pan if none is left. */
	Action DemoAction() const
	{
		Solver S(Line, Diff->Cap, Diff->Tolerance, Diff->Bench);
		const Action Found = S.Solve(Index, Difference(), Held);
		if (!(Found == NoAction) && !(Index == Diff->Shards && Held.N == 0)) return Found;
		std::array<Action, 3 + 2 * MaxBench> Acts{};
		const int Count = Actions(Acts);
		const Action LeftNext{ Kind::Left, Action::Next };
		if (Difference() <= 0 && Count > 0 && Acts[0] == LeftNext) return LeftNext;
		return Count > 1 ? Acts[1] : Acts[0];
	}

	/** Python's list repr of the bench: "[9, 3]" or "[]". */
	std::string BenchString() const
	{
		std::string Out = "[";
		for (int I = 0; I < Held.N; ++I) { if (I) Out += ", "; Out += std::to_string(Held.W[static_cast<size_t>(I)]); }
		return Out + "]";
	}
	static std::string Ints(const int* V, int N)
	{
		if (N == 0) return "-";
		std::string Out;
		for (int I = 0; I < N; ++I) { if (I) Out.push_back(','); Out += std::to_string(V[I]); }
		return Out;
	}
	std::string LineString() const { return Ints(Line.data(), static_cast<int>(Line.size())); }
	std::string HeldString() const { return Ints(Held.W.data(), Held.N); }
};

/** The parity text for an action: l, r, hold, l<n>, r<n>. */
inline std::string ActionText(const Action& A)
{
	if (A.K == Kind::Hold) return "hold";
	return std::string(A.K == Kind::Left ? "l" : "r") + (A.Source == Action::Next ? "" : std::to_string(A.Source));
}
inline bool ActionFromText(const std::string& Text, Action& Out)
{
	if (Text == "hold") { Out = { Kind::Hold, Action::Next }; return true; }
	if (Text.empty() || (Text[0] != 'l' && Text[0] != 'r')) return false;
	Out.K = Text[0] == 'l' ? Kind::Left : Kind::Right;
	if (Text.size() == 1) { Out.Source = Action::Next; return true; }
	for (size_t I = 1; I < Text.size(); ++I) if (Text[I] < '0' || Text[I] > '9') return false;
	Out.Source = std::stoi(Text.substr(1));
	return true;
}

} } // namespace daedalus::shardscale
